type Livre = { id: number; titre: string };
function estLivre(valeur: unknown): valeur is Livre {
  if (typeof valeur !== "object" || valeur === null) return false;
  const objet = valeur as Record<string, unknown>;
  return typeof objet.id === "number" && Number.isInteger(objet.id) && typeof objet.titre === "string";
}
const donnees: unknown = JSON.parse("{\"id\":1,\"titre\":\"Web\"}");
if (!estLivre(donnees)) throw new Error("Réponse invalide");
console.log(donnees.titre);
